merge_lists <- function(list1, list2) {
  result_list <- list()
  len1 <- length(list1)
  len2 <- length(list2)
  total_length <- len1 + len2

  if (is.atomic(list1) && is.atomic(list2)) {
    # If both are atomic vectors, combine them directly
    merged_vector <- c(list1, list2)
    return(merged_vector)
  }

  # Ensure both inputs are treated as lists for consistent merging
  if (is.atomic(list1) && !is.list(list1)) {
    list1 <- as.list(list1)
  }
  if (is.atomic(list2) && !is.list(list2)) {
    list2 <- as.list(list2)
  }

  merged_elements <- c()
  current_index <- 1

  for (i in seq_along(list1)) {
    element_to_add <- list1[[i]]
    merged_elements[[current_index]] <- element_to_add
    current_index <- current_index + 1
  }

  for (j in seq_along(list2)) {
    another_element <- list2[[j]]
    merged_elements[[current_index]] <- another_element
    current_index <- current_index + 1
  }

  final_list <- merged_elements
  return(final_list)
}

