is_prime <- function(n) {
  if (n <= 1) {
    return(FALSE)
  }
  if (n == 2) {
    return(TRUE)
  }
  if (n %% 2 == 0) {
    return(FALSE)
  }

  limit <- floor(sqrt(n))
  i <- 3
  while (i <= limit) {
    remainder <- n %% i
    if (remainder == 0) {
      return(FALSE)
    }
    i <- i + 2
  }

  result <- TRUE
  return(result)
}

