list_to_named_vector <- function(input_list) {
  names_vec <- c()
  values_vec <- c()

  if (length(input_list) == 0) {
    result_vector <- c()
    return(result_vector)
  }

  for (item in input_list) {
    current_name <- item[1]
    current_value <- item[2]

    names_vec <- c(names_vec, current_name)
    values_vec <- c(values_vec, current_value)
  }

  named_output <- setNames(values_vec, names_vec)

  return(named_output)
}

