is_leap_year <- function(year) {
  divisible_by_4 <- year %% 4 == 0
  divisible_by_100 <- year %% 100 == 0
  divisible_by_400 <- year %% 400 == 0

  is_leap <- FALSE

  if (divisible_by_4) {
    if (divisible_by_100) {
      if (divisible_by_400) {
        is_leap <- TRUE
      } else {
        is_leap <- FALSE
      }
    } else {
      is_leap <- TRUE
    }
  } else {
    is_leap <- FALSE
  }

  return(is_leap)
}

