generate_password <- function(length) {
  if (!is.numeric(length) || length <= 0) {
    stop("Length must be a positive integer.")
  }

  pool_chars <- c(letters, 0:9)
  num_chars_in_pool <- length(pool_chars)

  random_indices <- sample(1:num_chars_in_pool, size = length, replace = TRUE)
  selected_chars <- pool_chars[random_indices]

  password <- paste(selected_chars, collapse = "")

  return(password)
}

