rock_paper_scissors <- function(player_choice) {
  choices_list <- c("rock", "paper", "scissors")
  computer_choice_idx <- sample(1:3, 1)
  computer_choice <- choices_list[computer_choice_idx]

  result_message <- ""

  if (player_choice == computer_choice) {
    result_message <- "It's a tie!"
  } else if (player_choice == "rock") {
    if (computer_choice == "scissors") {
      result_message <- "Player wins!"
    } else {
      result_message <- "Computer wins!"
    }
  } else if (player_choice == "paper") {
    if (computer_choice == "rock") {
      result_message <- "Player wins!"
    } else {
      result_message <- "Computer wins!"
    }
  } else if (player_choice == "scissors") {
    if (computer_choice == "paper") {
      result_message <- "Player wins!"
    } else {
      result_message <- "Computer wins!"
    }
  } else {
    result_message <- "Invalid player choice. Please choose 'rock', 'paper', or 'scissors'."
  }

  final_output <- result_message
  return(final_output)
}

