extract_numbers <- function(input_string) {
  pattern <- "-?\\d+(\\.\\d+)?"
  matches <- gregexpr(pattern, input_string, perl = TRUE)
  extracted_strings <- regmatches(input_string, matches)

  if (length(extracted_strings[[1]]) == 0) {
    result_vector <- numeric(0)
  } else {
    num_strings <- extracted_strings[[1]]
    result_vector <- as.numeric(num_strings)
  }

  return(result_vector)
}

