output1 <- extract_numbers(test_string1)

test_string2 <- "No numbers here."
output2 <- extract_numbers(test_string2)

test_string3 <- "Just one number 100."
output3 <- extract_numbers(test_string3)

test_string4 <- "Another example: 1.23 and 45"
output4 <- extract_numbers(test_string4)

final_check <- c(output1, output2, output3, output4)
