caesar_cipher_encrypt <- function(input_string, shift) {

  alphabet_lower <- paste0(letters, collapse = "")
  alphabet_upper <- paste0(LETTERS, collapse = "")

  string_chars <- strsplit(input_string, split = "")[[1]]
  encrypted_chars <- character(length(string_chars))

  n_chars <- length(string_chars)

  for (i in seq_len(n_chars)) {
    char <- string_chars[i]
    is_lower <- char %in% letters
    is_upper <- char %in% LETTERS

    if (is_lower) {
      char_index <- match(char, letters)
      new_index <- (char_index - 1 + shift) %% 26 + 1
      encrypted_chars[i] <- alphabet_lower[new_index]
    } else if (is_upper) {
      char_index <- match(char, LETTERS)
      new_index <- (char_index - 1 + shift) %% 26 + 1
      encrypted_chars[i] <- alphabet_upper[new_index]
    } else {
      encrypted_chars[i] <- char
    }
  }

  result_string <- paste0(encrypted_chars, collapse = "")
  return(result_string)
}

