string_permutations <- function(s) {
  s_chars <- strsplit(s, "")[[1]]
  n_chars <- length(s_chars)

  if (n_chars == 0) {
    return(character(0))
  }

  if (n_chars == 1) {
    return(s)
  }

  generate_permutations <- function(chars) {
    n <- length(chars)

    if (n == 1) {
      return(chars)
    }

    perms_list <- list()
    for (i in seq_len(n)) {
      char_i <- chars[i]
      remaining_chars <- chars[-i]
      sub_permutations <- generate_permutations(remaining_chars)

      for (sub_perm in sub_permutations) {
        new_perm <- paste0(char_i, sub_perm)
        perms_list[[length(perms_list) + 1]] <- new_perm
      }
    }
    unique_perms <- unique(unlist(perms_list))
    return(unique_perms)
  }

  result_vector <- generate_permutations(s_chars)
  return(result_vector)
}

