can_schedule_task <- function(current_time_str, required_duration_min, available_slot_start_str, available_slot_end_str) {
  time_to_minutes <- function(time_str) {
    parts <- as.numeric(strsplit(time_str, ":")[[1]])
    minutes <- parts[1] * 60 + parts[2]
    return(minutes)
  }

  current_time_minutes <- time_to_minutes(current_time_str)
  slot_start_minutes <- time_to_minutes(available_slot_start_str)
  slot_end_minutes <- time_to_minutes(available_slot_end_str)

  earliest_start_time_for_task <- max(current_time_minutes, slot_start_minutes)

  task_end_time <- earliest_start_time_for_task + required_duration_min

  is_slot_valid <- slot_end_minutes > slot_start_minutes

  is_task_within_slot <- task_end_time <= slot_end_minutes

  can_schedule <- is_task_within_slot && is_slot_valid && earliest_start_time_for_task >= slot_start_minutes

  return(can_schedule)
}

