convert_mass <- function(value, from_unit, to_unit) {
  conversion_factor <- 2.20462

  if (from_unit == "kg" && to_unit == "lbs") {
    result <- value * conversion_factor
  } else if (from_unit == "lbs" && to_unit == "kg") {
    result <- value / conversion_factor
  } else if (from_unit == to_unit) {
