generate_times_table <- function(number, limit) {

  start_value <- 1
  end_value <- limit

  if (end_value < start_value) {
    result_vector <- character(0)
    return(result_vector)
  }

  sequence_numbers <- start_value:end_value

  formatted_entries <- character(length(sequence_numbers))

  i <- 1
  for (multiplier in sequence_numbers) {
    product_value <- number * multiplier

    entry_string <- paste(number, "*", multiplier, "=", product_value)

    formatted_entries[i] <- entry_string

    i <- i + 1
  }

  final_table <- formatted_entries

  return(final_table)
}

