generate_combinations <- function(vec, k) {
  n <- length(vec)

  if (k < 0 || k > n) {
    stop("k must be between 0 and the length of vec")
  }

  if (k == 0) {
    return(list(vector(mode = typeof(vec), length = 0)))
  }

  if (k == n) {
    return(list(vec))
  }

  indices <- seq_len(n)

  helper <- function(current_vec, start_index, remaining_k) {
    if (remaining_k == 0) {
      return(list(current_vec))
    }

    if (start_index > n) {
      return(list())
    }

    results <- list()

    for (i in start_index:n) {
      new_current_vec <- c(current_vec, vec[i])
      sub_combinations <- helper(new_current_vec, i + 1, remaining_k - 1)
      results <- c(results, sub_combinations)
    }

    return(results)
  }

  initial_vec <- vector(mode = typeof(vec), length = 0)

  all_combinations <- helper(initial_vec, 1, k)

  final_list <- all_combinations

  return(final_list)
}

