update_record_item <- function(records, item_id, new_value_name, new_value) {
  updated_records <- records
  record_count <- length(records)

  if (record_count == 0) {
    return(updated_records)
  }

  for (i in seq_along(updated_records)) {
    current_record <- updated_records[[i]]
    current_id <- as.numeric(current_record["id"])

    if (current_id == item_id) {
      current_record[[new_value_name]] <- new_value
      updated_records[[i]] <- current_record
      break
    }
  }

  return(updated_records)
}

