generate_random_letters <- function(count, uppercase = TRUE) {

  if (!is.numeric(count) || count < 0) {
    stop("Count must be a non-negative number.")
  }

  if (!is.logical(uppercase)) {
    stop("Uppercase must be a logical value (TRUE/FALSE).")
  }

  all_letters_upper <- LETTERS
  all_letters_lower <- letters

  if (uppercase) {
    available_letters <- all_letters_upper
  } else {
    available_letters <- all_letters_lower
  }

  num_letters <- length(available_letters)
  random_indices <- sample(seq_len(num_letters), size = count, replace = TRUE)

  result_vector <- available_letters[random_indices]

  return(result_vector)
}

