parse_query_params <- function(url_string) {
  query_start_index <- regexpr("\\?", url_string)

  if (query_start_index == -1) {
    result_list <- list()
    return(result_list)
  }

  query_string <- substr(url_string, query_start_index + 1, nchar(url_string))

  if (nchar(query_string) == 0) {
    result_list <- list()
    return(result_list)
  }

  param_pairs <- strsplit(query_string, "&")[[1]]

  decoded_params <- list()

  for (pair in param_pairs) {
    key_value_split <- strsplit(pair, "=")[[1]]
    param_name <- URLdecode(key_value_split[1])

    if (length(key_value_split) > 1) {
      param_value <- URLdecode(key_value_split[2])
    } else {
      param_value <- ""
    }

    decoded_params[[param_name]] <- param_value
  }

  final_result <- decoded_params
  return(final_result)
}

