is_balanced_parentheses <- function(s) {
  stack <- c()
  mapping <- list(
    ")" = "(",
    "]" = "[",
    "}" = "{"
  )

  open_brackets <- names(mapping)
  close_brackets <- unlist(mapping)

  s_chars <- strsplit(s, "")[[1]]

  for (char in s_chars) {
    is_open <- char %in% close_brackets
    is_close <- char %in% open_brackets

    if (is_open) {
      stack <- c(stack, char)
    } else if (is_close) {
      if (length(stack) == 0) {
        return(FALSE)
      }

      top_element <- stack[length(stack)]
      expected_open <- mapping[[char]]

      if (top_element != expected_open) {
        return(FALSE)
      }

      stack <- stack[-length(stack)]
    }
  }

  result <- length(stack) == 0
  return(result)
}

