`roman_to_int` <- function(s) {
  `roman_map` <- list(
    "I" = 1, "V" = 5, "X" = 10, "L" = 50,
    "C" = 100, "D" = 500, "M" = 1000
  )
  `n` <- nchar(s)
  `total` <- 0
  `i` <- 1

  while (`i` <= `n`) {
    `current_char` <- substr(s, `i`, `i`)
    `current_val` <- `roman_map`[[current_char]]

    `next_val` <- 0
    if (`i` < `n`) {
      `next_char` <- substr(s, `i` + 1, `i` + 1)
      `next_val` <- `roman_map`[[next_char]]
    }

    if (`next_val` > `current_val`) {
      `total` <- `total` + (`next_val` - `current_val`)
      `i` <- `i` + 2
    } else {
      `total` <- `total` + `current_val`
      `i` <- `i` + 1
    }
  }
  return(`total`)
}

`result1` <- `roman_to_int`("IX")
`result2` <- `roman_to_int`("LVIII")
`result3` <- `roman_to_int`("MCMXCIV")
`result4` <- `roman_to_int`("MMMCMXCIX")
`final_result` <- c(`result1`, `result2`, `result3`, `result4`)

