  ip_parts <- strsplit(ip_string, ".", fixed = TRUE)[[1]]
  num_parts <- length(ip_parts)

  if (num_parts != 4) {
    return(FALSE)
  }

  all_parts_valid <- TRUE

  for (part in ip_parts) {
    numeric_part <- suppressWarnings(as.numeric(part))

    if (is.na(numeric_part)) {
      all_parts_valid <- FALSE
      break
    }

    if (numeric_part < 0 || numeric_part > 255 || floor(numeric_part) != numeric_part) {
      all_parts_valid <- FALSE
      break
