levenshtein_distance <- function(s1, s2) {
  n1 <- nchar(s1)
  n2 <- nchar(s2)

  if (n1 == 0) {
    return(n2)
  }
  if (n2 == 0) {
    return(n1)
  }

  d <- matrix(0, nrow = n1 + 1, ncol = n2 + 1)

  for (i in 0:n1) {
    d[i + 1, 1] <- i
  }

  for (j in 0:n2) {
    d[1, j + 1] <- j
  }

  for (j in 2:(n2 + 1)) {
    for (i in 2:(n1 + 1)) {
      s1_char <- substr(s1, i - 1, i - 1)
      s2_char <- substr(s2, j - 1, j - 1)

      cost <- ifelse(s1_char == s2_char, 0, 1)

      insertion <- d[i, j - 1] + 1
      deletion <- d[i - 1, j] + 1
      substitution <- d[i - 1, j - 1] + cost

      d[i, j] <- min(insertion, deletion, substitution)
    }
  }

  final_distance <- d[n1 + 1, n2 + 1]
  return(final_distance)
}

# Example usage:
result1 <- levenshtein_distance("kitten", "sitting")
result2 <- levenshtein_distance("flaw", "lawn")
result3 <- levenshtein_distance("hello", "hola")
result4 <- levenshtein_distance("", "abc")
result5 <- levenshtein_distance("abc", "")
result6 <- levenshtein_distance("abc", "abc")

