categorize_ages <- function(ages_vec) {
  num_ages <- length(ages_vec)
  categories_char <- character(num_ages)

  for (i in seq_len(num_ages)) {
    age_val <- ages_vec[i]
    if (age_val >= 0 && age_val <= 12) {
      categories_char[i] <- "Child"
    } else if (age_val >= 13 && age_val <= 19) {
      categories_char[i] <- "Teen"
    } else if (age_val >= 20 && age_val <= 64) {
      categories_char[i] <- "Adult"
    } else if (age_val >= 65) {
      categories_char[i] <- "Senior"
    } else {
      categories_char[i] <- NA_character_
    }
  }

  levels_order <- c("Child", "Teen", "Adult", "Senior")
  result_factor <- factor(categories_char, levels = levels_order)
  return(result_factor)
}

