schedule_event <- function(existing_events, new_event) {

  overlap_threshold <- 30 * 60 

  if (length(existing_events) == 0) {
    return(TRUE)
  }

  new_event_start <- new_event

  no_overlap_found <- TRUE

  for (event_time in existing_events) {

    event_start <- event_time

    time_diff <- abs(as.numeric(difftime(new_event_start, event_start, units = "secs")))

    if (time_diff < overlap_threshold) {
      no_overlap_found <- FALSE
      break
    }
  }

  result <- no_overlap_found

  return(result)
}

