is_palindrome_number <- function(x) {
  if (x < 0) {
    return(FALSE)
  }

  original_number <- x
  reversed_number <- 0

  while (x > 0) {
    last_digit <- x %% 10
    reversed_number <- reversed_number * 10 + last_digit
    x <- floor(x / 10)
  }

  is_equal <- original_number == reversed_number
  return(is_equal)
}

