count_text_words <- function(text_string) {
  text_string_lower <- tolower(text_string)
  cleaned_text <- gsub("[[:punct:]]", "", text_string_lower)
  words_vector <- strsplit(cleaned_text, "\\s+")[[1]]
  words_vector <- words_vector[words_vector != ""]

  if (length(words_vector) == 0) {
    return(list())
  }

  word_counts <- table(words_vector)
  result_list <- as.list(word_counts)
  names(result_list) <- names(word_counts)

  sorted_names <- sort(names(result_list))
  final_result <- result_list[sorted_names]

  return(final_result)
}

