days_until_birthday <- function(birth_date) {
  today <- Sys.Date()
  current_year <- as.numeric(format(today, "%Y"))
  birth_month_day <- format(birth_date, "%m-%d")

  next_birthday_this_year_str <- paste0(current_year, "-", birth_month_day)
  next_birthday_this_year <- as.Date(next_birthday_this_year_str)

  if (next_birthday_this_year >= today) {
    days_left <- as.numeric(next_birthday_this_year - today)
  } else {
    next_year <- current_year + 1
    next_birthday_next_year_str <- paste0(next_year, "-", birth_month_day)
    next_birthday_next_year <- as.Date(next_birthday_next_year_str)
    days_left <- as.numeric(next_birthday_next_year - today)
  }

  # Special handling for Feb 29 on non-leap years
  if (format(birth_date, "%m-%d") == "02-29") {
    is_leap_year <- function(year) {
      leap_check1 <- year %% 4 == 0
      leap_check2 <- year %% 100 != 0
      leap_check3 <- year %% 400 == 0
      result <- (leap_check1 && leap_check2) || leap_check3
      return(result)
    }

    current_year_is_leap <- is_leap_year(current_year)
    next_year_is_leap <- is_leap_year(current_year + 1)

    if (next_birthday_this_year < today && !next_year_is_leap) {
      # If next birthday in next year would be Feb 29 but next year is not a leap year,
      # it falls on March 1.
      adjusted_next_birthday_next_year_str <- paste0(current_year + 1, "-03-01")
      adjusted_next_birthday_next_year <- as.Date(adjusted_next_birthday_next_year_str)
      days_left <- as.numeric(adjusted_next_birthday_next_year - today)
    } else if (next_birthday_this_year >= today && !current_year_is_leap) {
      # If birthday is Feb 29 this year, but this year is not a leap year,
      # it falls on March 1.
      adjusted_next_birthday_this_year_str <- paste0(current_year, "-03-01")
      adjusted_next_birthday_this_year <- as.Date(adjusted_next_birthday_this_year_str)
      days_left <- as.numeric(adjusted_next_birthday_this_year - today)
    }
  }

  return(days_left)
}

