longest_common_prefix <- function(strs) {
  num_strings <- length(strs)
  if (num_strings == 0) {
    return("")
  }

  if (num_strings == 1) {
    return(strs[[1]])
  }

  first_string <- strs[[1]]
  min_len <- nchar(first_string)

  for (i in 2:num_strings) {
    current_string <- strs[[i]]
    current_len <- nchar(current_string)
    if (current_len < min_len) {
      min_len <- current_len
    }
  }

  prefix <- ""
  for (i in 1:min_len) {
    current_char <- substr(first_string, i, i)
    is_common <- TRUE
    for (j in 2:num_strings) {
      if (substr(strs[[j]], i, i) != current_char) {
        is_common <- FALSE
        break
      }
    }
    if (is_common) {
      prefix <- paste0(prefix, current_char)
    } else {
      break
    }
  }
  return(prefix)
}

