queue_operations <- function(initial_queue, operations) {
  current_queue <- initial_queue
  op_results <- list()
  idx_result <- 1

  for (op in operations) {
    op_type <- op$type
    if (op_type == "enqueue") {
      value_to_add <- op$value
      current_queue <- c(current_queue, value_to_add)
      op_results[[idx_result]] <- list(type = "enqueue_result", queue = current_queue)
      idx_result <- idx_result + 1
    } else if (op_type == "dequeue") {
      if (length(current_queue) > 0) {
        dequeued_item <- current_queue[[1]]
        current_queue <- current_queue[-1]
        op_results[[idx_result]] <- list(type = "dequeue_result", item = dequeued_item, queue = current_queue)
        idx_result <- idx_result + 1
      } else {
        dequeued_item <- NULL
        op_results[[idx_result]] <- list(type = "dequeue_result", item = dequeued_item, queue = current_queue)
        idx_result <- idx_result + 1
      }
    }
  }
  final_queue <- current_queue
  return(final_queue)
}

