generate_date_range <- function(start_date, end_date) {

  start_date_val <- as.Date(start_date)
  end_date_val <- as.Date(end_date)

  if (start_date_val > end_date_val) {
    stop_message <- "Start date must be less than or equal to end date."
    stop(stop_message)
  }

  date_sequence <- seq(from = start_date_val, to = end_date_val, by = "day")

  result_vector <- as.Date(date_sequence)

  list_length <- length(result_vector)

  if (list_length == 0) {
    empty_vector <- vector("Date")
    return(empty_vector)
  }

  return(result_vector)
}

