filter_list_of_records <- function(records, key, value) {

  filtered_records <- list()

  for (i in seq_along(records)) {
    current_record <- records[[i]]

    if (key %in% names(current_record)) {

      record_value <- current_record[[key]]

      if (record_value == value) {

        filtered_records <- c(filtered_records, list(current_record))
      }
    }
  }

  return(filtered_records)
}

