update_named_list_value <- function(my_list, key_to_update, new_value) {
  result_list <- my_list

  keys_exist <- names(result_list)
  key_is_present <- key_to_update %in% keys_exist

  if (key_is_present) {
    result_list[[key_to_update]] <- new_value
  } else {
    new_element <- list(new_value)
    names(new_element) <- key_to_update
    result_list <- c(result_list, new_element)
  }

  return(result_list)
}

