calculate_factorial <- function(n) {
  result <- 1
  input_n <- n

  if (input_n < 0) {
    stop("Factorial is not defined for negative numbers.")
  } else if (input_n == 0) {
    result <- 1
  } else {
    i <- 1
    while (i <= input_n) {
      result <- result * i
      i <- i + 1
    }
  }

  final_result <- as.integer(result)
  return(final_result)
}

