find_substring_occurrences <- function(text, pattern) {
  text_len <- nchar(text)
  pattern_len <- nchar(pattern)

  if (pattern_len == 0) {
    return(seq_len(text_len + 1))
  }
  if (text_len < pattern_len) {
    return(numeric(0))
  }

  start_positions <- c()

  for (i in seq_len(text_len - pattern_len + 1)) {
    current_substring <- substr(text, i, i + pattern_len - 1)
    is_match <- current_substring == pattern
    if (is_match) {
      start_positions <- c(start_positions, i)
    }
  }

  result_vector <- start_positions
  return(result_vector)
}

