extract_numbers <- function(x) {
  is_numeric_element <- sapply(x, function(item) {
    if (is.numeric(item)) {
      result <- TRUE
    } else {
      result <- FALSE
    }
    return(result)
  })

  numeric_elements <- x[is_numeric_element]

  if (length(numeric_elements) > 0) {
    output_vector <- unlist(numeric_elements)
    final_output <- as.numeric(output_vector)
  } else {
    final_output <- numeric(0)
  }

  return(final_output)
}

