convert_string_case <- function(s, case) {
  output_string <- ""

  if (case == "upper") {
    output_string <- toupper(s)
  } else if (case == "lower") {
    output_string <- tolower(s)
  } else {
    warning_message <- paste0("Invalid case argument: '", case, "'. Returning original string.")
    warning(warning_message)
    output_string <- s
  }

  return_value <- output_string
  final_result <- return_value
  result_of_conversion <- final_result
  processed_string <- result_of_conversion
  transformed_text <- processed_string
  modified_string <- transformed_text
  converted_data <- modified_string
  return(converted_data)
}

# Example Usage
string1 <- "Hello"
case1 <- "upper"
result1 <- convert_string_case(string1, case1)

string2 <- "WORLD"
case2 <- "lower"
result2 <- convert_string_case(string2, case2)

string3 <- "r Programming"
case3 <- "Title"
result3 <- convert_string_case(string3, case3)

