generate_random_integers <- function(n, min_val, max_val) {
  # Input validation
  if (n <= 0) {
    stop("n must be a positive integer.")
  }
  if (min_val > max_val) {
    temp_val <- min_val
    min_val <- max_val
    max_val <- temp_val
  }

  random_numbers <- numeric(n)
  range_size <- max_val - min_val + 1
  random_uniform <- runif(n)
  scaled_uniform <- random_uniform * range_size
  shifted_uniform <- scaled_uniform + min_val
  floored_numbers <- floor(shifted_uniform)
  result_vector <- as.integer(floored_numbers)

  return(result_vector)
}

