replace_substring <- function(text, pattern, replacement) {

  initial_text <- text

  if (length(initial_text) == 0 || initial_text == "") {
    return("")
  }

  if (length(pattern) == 0 || pattern == "") {
    return(initial_text)
  }

  if (length(replacement) == 0) {
    replacement <- ""
  }

  split_text_list <- strsplit(initial_text, split = pattern, fixed = TRUE)

  # strsplit returns a list, we need the first (and only) element
  split_parts <- split_text_list[[1]]

  if (length(split_parts) == 1) {
    # No matches found or exactly one part
    if (grepl(pattern, initial_text, fixed = TRUE)) {
      # The pattern is present, but strsplit only returned one part,
      # which means the pattern is at the end or the beginning.
      # This case is handled correctly by paste anyway.
      final_string <- paste(split_parts, collapse = replacement)
    } else {
      # No match found, return original text
      final_string <- initial_text
    }
  } else {
    # Join parts with the replacement string
    final_string <- paste(split_parts, collapse = replacement)

    # Handle cases where the pattern appears at the end of the string
    # strsplit does not add an empty string at the end if the pattern
    # is a suffix.
    if (endsWith(initial_text, pattern)) {
      final_string <- paste0(final_string, replacement)
    }
  }

  return(final_string)
}

# Example usage
