test_pattern_1 <- "world"
test_replacement_1 <- "R"
result_1 <- replace_substring(test_text_1, test_pattern_1, test_replacement_1)

test_text_2 <- "banana"
test_pattern_2 <- "a"
test_replacement_2 <- "o"
result_2 <- replace_substring(test_text_2, test_pattern_2, test_replacement_2)

test_text_3 <- "this is a test string test"
test_pattern_3 <- "test"
